#!/usr/bin/env python3
"""Patches the Android project generated by `npx cap add android`:
- share intent (the app shows up in the Android "Share" menu), notification permissions, MainActivity,
- app icon (drawn here with Pillow, no image files needed),
- version: versionName 1.<BUILD_NUMBER>, versionCode <BUILD_NUMBER>, plus www/version.js shown inside the app,
- fixed signing key, so every new APK installs over the previous one,
- www/config.js with the built-in AI key (from GitHub Secrets AI_API_KEY / AI_PROVIDER / AI_MODEL).
"""
import base64
import datetime
import json
import math
import os
import re
import sys

# Stały klucz podpisu (debug). Dzięki niemu każdy kolejny APK ma ten sam podpis i da się go zainstalować na wierzch.
DEBUG_KEYSTORE_B64 = ""

C_TOP, C_BOTTOM = (255, 170, 84), (214, 72, 28)
WHITE = (255, 255, 255, 255)


# ---------------------------------------------------------------- ikona
def _gradient(n):
    from PIL import Image, ImageOps
    g = Image.linear_gradient('L').resize((n, n), Image.BILINEAR)
    return ImageOps.colorize(g, C_TOP, C_BOTTOM).convert('RGBA')


def _sun(n):
    """Białe słońce na przezroczystym tle; promienie mieszczą się w strefie bezpiecznej ikony adaptacyjnej."""
    from PIL import Image, ImageDraw
    k = 4
    big = n * k
    im = Image.new('RGBA', (big, big), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    c = big / 2
    R = big * 0.30
    r = R * 0.50
    d.ellipse([c - r, c - r, c + r, c + r], fill=WHITE)
    w = float(int(R * 0.20))
    for i in range(8):
        a = math.radians(i * 45)
        x1, y1 = c + math.cos(a) * R * 0.72, c + math.sin(a) * R * 0.72
        x2, y2 = c + math.cos(a) * R, c + math.sin(a) * R
        d.line([x1, y1, x2, y2], fill=WHITE, width=int(w))
        for x, y in ((x1, y1), (x2, y2)):
            d.ellipse([x - w / 2, y - w / 2, x + w / 2, y + w / 2], fill=WHITE)
    return im.resize((n, n), Image.LANCZOS)


def _mask(n, shape):
    from PIL import Image, ImageDraw
    k = 4
    m = Image.new('L', (n * k, n * k), 0)
    d = ImageDraw.Draw(m)
    if shape == 'circle':
        d.ellipse([0, 0, n * k - 1, n * k - 1], fill=255)
    else:
        d.rounded_rectangle([0, 0, n * k - 1, n * k - 1], radius=int(n * k * 0.22), fill=255)
    return m.resize((n, n), Image.LANCZOS)


def render_legacy(n, shape='square'):
    from PIL import Image
    base = _gradient(n)
    base.alpha_composite(_sun(n))
    out = Image.new('RGBA', (n, n), (0, 0, 0, 0))
    out.paste(base, (0, 0), _mask(n, shape))
    return out


def make_icons(res):
    legacy = {'mdpi': 48, 'hdpi': 72, 'xhdpi': 96, 'xxhdpi': 144, 'xxxhdpi': 192}
    adaptive = {'mdpi': 108, 'hdpi': 162, 'xhdpi': 216, 'xxhdpi': 324, 'xxxhdpi': 432}
    for dens in legacy:
        d = os.path.join(res, 'mipmap-' + dens)
        os.makedirs(d, exist_ok=True)
        render_legacy(legacy[dens], 'square').save(os.path.join(d, 'ic_launcher.png'))
        render_legacy(legacy[dens], 'circle').save(os.path.join(d, 'ic_launcher_round.png'))
        _sun(adaptive[dens]).save(os.path.join(d, 'ic_launcher_foreground.png'))
        _gradient(adaptive[dens]).save(os.path.join(d, 'ic_launcher_bg.png'))
    any26 = os.path.join(res, 'mipmap-anydpi-v26')
    os.makedirs(any26, exist_ok=True)
    xml = ('<?xml version="1.0" encoding="utf-8"?>\n'
           '<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n'
           '    <background android:drawable="@mipmap/ic_launcher_bg"/>\n'
           '    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>\n'
           '</adaptive-icon>\n')
    for name in ('ic_launcher.xml', 'ic_launcher_round.xml'):
        open(os.path.join(any26, name), 'w', encoding='utf-8').write(xml)
    vals = os.path.join(res, 'values')
    os.makedirs(vals, exist_ok=True)
    open(os.path.join(vals, 'ic_launcher_background.xml'), 'w', encoding='utf-8').write(
        '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <color name="ic_launcher_background">#EE7A38</color>\n</resources>\n')


# ---------------------------------------------------------------- ekran startowy (splash)
SPLASH_BG = (234, 121, 56)  # środek gradientu ikony; ten sam kolor w Androidzie 12+


def make_splash(res):
    """Podmienia domyślny ekran startowy Capacitor (białe tło + logo) na pomarańczowe tło z białym słońcem
    i ustawia go także dla Androida 12+ (windowSplashScreen*)."""
    import glob
    from PIL import Image
    paths = glob.glob(os.path.join(res, 'drawable*', 'splash.png'))
    if not paths:
        os.makedirs(os.path.join(res, 'drawable'), exist_ok=True)
        paths = [os.path.join(res, 'drawable', 'splash.png')]
    for p in paths:
        try:
            w, h = Image.open(p).size
        except Exception:
            w, h = 480, 320
        n = int(min(w, h) * 0.34)
        img = Image.new('RGBA', (w, h), SPLASH_BG + (255,))
        img.alpha_composite(_sun(n), ((w - n) // 2, (h - n) // 2))
        img.convert('RGB').save(p)
    vals = os.path.join(res, 'values')
    os.makedirs(vals, exist_ok=True)
    open(os.path.join(vals, 'mojdzien_splash.xml'), 'w', encoding='utf-8').write(
        '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n    <color name="splash_bg">#%02X%02X%02X</color>\n</resources>\n' % SPLASH_BG)
    sp = os.path.join(vals, 'styles.xml')
    if os.path.exists(sp):
        s = open(sp, encoding='utf-8').read()
        if 'windowSplashScreenBackground' not in s:
            s, n = re.subn(
                r'(<style name="AppTheme\.NoActionBarLaunch"[^>]*>)(.*?)(</style>)',
                lambda mm: mm.group(1) + mm.group(2) +
                '    <item name="windowSplashScreenBackground">@color/splash_bg</item>\n'
                '        <item name="windowSplashScreenAnimatedIcon">@mipmap/ic_launcher_foreground</item>\n    ' + mm.group(3),
                s, count=1, flags=re.S)
            if n:
                open(sp, 'w', encoding='utf-8').write(s)
            else:
                print('WARNING: AppTheme.NoActionBarLaunch not found in styles.xml')


# ---------------------------------------------------------------- reszta
def main():
    build = (os.environ.get('BUILD_NUMBER') or '0').strip()
    version_name = '1.' + build
    version_code = int(build) if build.isdigit() and int(build) > 0 else 1

    cfg = json.load(open('capacitor.config.json', encoding='utf-8'))
    app_id = cfg['appId']

    manifest_path = 'android/app/src/main/AndroidManifest.xml'
    if not os.path.exists(manifest_path):
        sys.exit('AndroidManifest.xml not found - run `npx cap add android` first')

    m = open(manifest_path, encoding='utf-8').read()
    if 'android.intent.action.SEND' not in m:
        share = """
            <intent-filter>
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
                <data android:mimeType="text/plain" />
            </intent-filter>
        """
        m = m.replace('</activity>', share + '</activity>', 1)
    perms = ''
    for p in ('android.permission.POST_NOTIFICATIONS', 'android.permission.SCHEDULE_EXACT_ALARM', 'android.permission.RECEIVE_BOOT_COMPLETED'):
        if p not in m:
            perms += '    <uses-permission android:name="%s" />\n' % p
    if perms:
        m = re.sub(r'<application', perms + '    <application', m, count=1)
    if 'windowSoftInputMode' not in m:  # klawiatura zmniejsza widok zamiast go przykrywać
        m = re.sub(r'<activity\b', '<activity android:windowSoftInputMode="adjustResize"', m, count=1)
    open(manifest_path, 'w', encoding='utf-8').write(m)

    pkg_dir = os.path.join('android/app/src/main/java', *app_id.split('.'))
    os.makedirs(pkg_dir, exist_ok=True)
    java = """package %s;

import android.content.Intent;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import com.getcapacitor.BridgeActivity;
import org.json.JSONObject;

public class MainActivity extends BridgeActivity {
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        deliver(getIntent(), 1500);
    }

    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        setIntent(intent);
        deliver(intent, 200);
    }

    private void deliver(Intent intent, long delay) {
        if (intent == null || !Intent.ACTION_SEND.equals(intent.getAction())) return;
        String text = intent.getStringExtra(Intent.EXTRA_TEXT);
        if (text == null) return;
        String subject = intent.getStringExtra(Intent.EXTRA_SUBJECT);
        String payload = (subject != null && !text.contains(subject) ? subject + "\\n" : "") + text;
        intent.setAction(Intent.ACTION_MAIN);
        final String js = "window.__shared=" + JSONObject.quote(payload) + ";if(window.onShared)window.onShared();";
        new Handler(Looper.getMainLooper()).postDelayed(new Runnable() {
            @Override
            public void run() {
                if (getBridge() != null && getBridge().getWebView() != null) {
                    getBridge().getWebView().evaluateJavascript(js, null);
                }
            }
        }, delay);
    }
}
""" % app_id
    open(os.path.join(pkg_dir, 'MainActivity.java'), 'w', encoding='utf-8').write(java)

    # ikona
    try:
        make_icons('android/app/src/main/res')
        print('Icon: generated')
    except Exception as e:  # build nie powinien się wywrócić przez ikonę
        print('WARNING: icon not generated:', e)
    try:
        make_splash('android/app/src/main/res')
        print('Splash: generated')
    except Exception as e:
        print('WARNING: splash not generated:', e)

    # wersja aplikacji w systemie Android
    gp = 'android/app/build.gradle'
    if os.path.exists(gp):
        g = open(gp, encoding='utf-8').read()
        g2, n1 = re.subn(r'versionCode\s+\d+', 'versionCode %d' % version_code, g, count=1)
        g2, n2 = re.subn(r'versionName\s+"[^"]*"', 'versionName "%s"' % version_name, g2, count=1)
        if n1 and n2:
            open(gp, 'w', encoding='utf-8').write(g2)
        else:
            print('WARNING: versionCode/versionName not found in build.gradle')
    else:
        print('WARNING: android/app/build.gradle not found')

    # wersja widoczna w aplikacji + wbudowany klucz AI
    os.makedirs('www', exist_ok=True)
    now = datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%d %H:%M UTC')
    open('www/version.js', 'w', encoding='utf-8').write(
        'window.APP_VERSION=%s;window.APP_BUILD=%s;window.APP_DATE=%s;\n' % (json.dumps(version_name), json.dumps(build), json.dumps(now)))

    key = (os.environ.get('AI_API_KEY') or '').strip()
    provider = (os.environ.get('AI_PROVIDER') or '').strip().lower() or 'gemini'
    default_models = {'gemini': 'gemini-2.5-flash', 'anthropic': 'claude-sonnet-5-5', 'openai': 'llama-3.3-70b-versatile'}
    model = (os.environ.get('AI_MODEL') or '').strip() or default_models.get(provider, '')
    base_url = (os.environ.get('AI_BASE_URL') or '').strip()
    conf = {'apiKey': key, 'provider': provider, 'model': model, 'baseUrl': base_url}
    open('www/config.js', 'w', encoding='utf-8').write('window.APP_CONFIG=%s;\n' % json.dumps(conf))
    print('AI key: %s' % ('built in (provider %s, model %s)' % (provider, model) if key else 'NOT SET (add the AI_API_KEY secret)'))

    ip = 'www/index.html'
    if os.path.exists(ip):
        h = open(ip, encoding='utf-8').read()
        tag = '<script src="app.js"></script>'
        if 'version.js' not in h and tag in h:
            h = h.replace(tag, '<script src="version.js"></script>\n<script src="config.js"></script>\n' + tag)
            open(ip, 'w', encoding='utf-8').write(h)

    # stały podpis
    ks_dir = os.path.join(os.path.expanduser('~'), '.android')
    os.makedirs(ks_dir, exist_ok=True)
    open(os.path.join(ks_dir, 'debug.keystore'), 'wb').write(base64.b64decode(DEBUG_KEYSTORE_B64))
    print('Signing key: fixed debug keystore installed')

    print('Android project patched OK - version %s (code %d)' % (version_name, version_code))


if __name__ == '__main__':
    main()
